recursos_actuales = {"recurso-a", "recurso-b", "recurso-c"}
recursos_en_plantilla = {"recurso-a", "recurso-b", "recurso-d"}

def aplicar_incremental(actuales, plantilla):
    resultado = set(actuales)
    resultado |= plantilla
    return resultado

def aplicar_completo(actuales, plantilla):
    return set(plantilla)

resultado_incremental = aplicar_incremental(recursos_actuales, recursos_en_plantilla)
resultado_completo = aplicar_completo(recursos_actuales, recursos_en_plantilla)

print("Modo incremental:", ", ".join(sorted(resultado_incremental)))
print("Modo completo:", ", ".join(sorted(resultado_completo)))
print("Eliminados solo en modo completo:", ", ".join(sorted(recursos_actuales - recursos_en_plantilla)))
